func parallelSum(nums []int, workers int) int {
    if workers < 1 {
        workers = 1
    }
    chunk := (len(nums) + workers - 1) / workers
    out := make(chan int, workers)
    for w := 0; w < workers; w++ {
        start := w * chunk
        end := start + chunk
        if start >= len(nums) {
            break
        }
        if end > len(nums) {
            end = len(nums)
        }
        part := nums[start:end]
        go func(p []int) {
            s := 0
            for _, n := range p {
                s += n
            }
            out <- s
        }(part)
    }
    total := 0
    for i := 0; i < workers && i*chunk < len(nums); i++ {
        total += <-out
    }
    return total
}

